var cutoff = Date.now() - 26 * 3600 * 1000;
var all = $input.all();
var out = [];
for (var i = 0; i < all.length; i++) {
  var it = all[i].json;
  var t = it.track || {};
  if (!it.added_at || new Date(it.added_at).getTime() < cutoff) continue;
  var artists = (t.artists || []).map(function (a) { return a.name; });
  out.push({ json: { uri: t.uri, name: t.name, artist: artists[0] || '', artists: artists.join(', '), artistId: (t.artists && t.artists[0]) ? t.artists[0].id : '', album: t.album ? t.album.name : '', year: (t.album && t.album.release_date) ? t.album.release_date.slice(0, 4) : '' } });
}
return out;

var s = $('Pick new songs').item.json;
var lf = $('Last.fm tags').item.json;
var tags = (lf.toptags && lf.toptags.tag) ? lf.toptags.tag.slice(0, 10).map(function (t) { return t.name; }) : [];
var genres = $json.genres || [];
var lines = [
  'Song: ' + s.name,
  'Artist(s): ' + s.artists,
  'Album: ' + s.album + ' (' + s.year + ')',
  'Last.fm tags: ' + (tags.length ? tags.join(', ') : 'none'),
  'Spotify artist genres: ' + (genres.length ? genres.join(', ') : 'none')
];
return { json: { uri: s.uri, name: s.name, artist: s.artists, tags: tags, genres: genres, prompt: lines.join('\n') } };

var map = { good_stuff: ['YOUR_PLAYLIST_ID_1', 'the good stuff'], turkce: ['YOUR_PLAYLIST_ID_2', 'turkce'], dunya_hitleri: ['YOUR_PLAYLIST_ID_3', 'just a 00s-10s girl'], brunch: ['YOUR_PLAYLIST_ID_4', 'the brunch playlist'], hype: ['YOUR_PLAYLIST_ID_5', 'volume up'], sunny: ['YOUR_PLAYLIST_ID_6', 'sunny side up'] };
var prompts = $('Build prompt').all();
var items = $input.all();
var out = [];
for (var i = 0; i < items.length; i++) {
  var j = items[i].json;
  var text = (j.content || []).filter(function (c) { return c.type === 'text'; }).map(function (c) { return c.text; }).join('');
  var parsed = { playlists: [] };
  try { parsed = JSON.parse(text.replace(/```json|```/g, '').trim()); } catch (e) {}
  var song = prompts[i] ? prompts[i].json : {};
  (parsed.playlists || []).forEach(function (p) {
    if (map[p.id] && p.confidence >= 0.75) {
      out.push({ json: { uri: song.uri, song: song.name, playlistId: map[p.id][0], playlist: map[p.id][1], confidence: p.confidence } });
    }
  });
}
return out;
